#include <stdio.h>
#include <stdint.h>

int main(void) {
    int cajas[4] = {10, 20, 30, 40};      /* 4 enteros contiguos en memoria */
    int *p = cajas;                        /* p apunta al primer elemento */

    printf("sizeof(int) = %zu bytes\n", sizeof(int));
    for (int i = 0; i < 4; i++) {
        printf("p + %d -> direccion %p (offset %ld bytes) valor %d\n",
               i, (void *)(p + i), (long)((char *)(p + i) - (char *)p), *(p + i));
    }
    printf("cajas[2] = %d, *(cajas + 2) = %d, 2[cajas] = %d\n", cajas[2], *(cajas + 2), 2[cajas]);

    char *q = (char *)cajas;               /* el mismo bloque, visto de a byte */
    printf("q + 1 avanza %ld byte; p + 1 avanza %ld bytes\n",
           (long)((q + 1) - q), (long)((char *)(p + 1) - (char *)p));

    int *fin = p + 4;                      /* una posicion pasada el final: legal, pero no se lee */
    int suma = 0;
    for (int *it = p; it != fin; it++) suma += *it;
    printf("suma recorriendo con un puntero: %d\n", suma);
    return 0;
}

// Una memoria simulada: 32 bytes numerados de 0 a 31 (es lo que ves en el
// diagrama de la RAM: casilleros con dirección). Todo "puntero" es un número.
const RAM = new ArrayBuffer(32);
const bytes = new Uint8Array(RAM);
const enteros = new Int32Array(RAM);       // la misma memoria, vista de a 4 bytes

const BASE = 8;                             // el arreglo "cajas" empieza en la dirección 8
const TAM_INT = 4;                          // sizeof(int)
[10, 20, 30, 40].forEach((v, i) => { enteros[(BASE / TAM_INT) + i] = v; });

// aritmética de punteros: p + i apunta a BASE + i * tamaño del tipo
const mas = (p, i, tam) => p + i * tam;
for (let i = 0; i < 4; i++) {
  const dir = mas(BASE, i, TAM_INT);
  console.log(`p + ${i} -> dirección ${dir}, valor ${enteros[dir / TAM_INT]}`);
}

// el mismo bloque mirado de a byte (como un char*): p + 1 avanza 1, no 4
console.log("bytes desde la dirección 8:", Array.from(bytes.slice(8, 16)).join(" "));

// un "puntero colgado": la dirección sigue siendo un número válido,
// pero el dato que había ahí puede haber sido reemplazado por otro
let p = mas(BASE, 2, TAM_INT);              // apunta al 30
console.log("antes de reutilizar:", enteros[p / TAM_INT]);
enteros[p / TAM_INT] = 9999;                // otra parte del programa reutiliza ese lugar
console.log("después de reutilizar:", enteros[p / TAM_INT], "(nadie avisó)");

// pasarse del final: acá la memoria simulada devuelve undefined; en C devolvería lo que haya
console.log("leer fuera de los 32 bytes:", enteros[100]);

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *a = malloc(4 * sizeof *a);       /* lugar para 4 enteros: indices 0 a 3 */
    for (int i = 0; i < 4; i++) a[i] = i + 1;
    printf("a[3] = %d\n", a[3]);
    printf("a[4] = %d   <- fuera del bloque\n", a[4]);   /* lee un entero que no es nuestro */
    free(a);
    printf("a[0] despues de free = %d\n", a[0]);          /* lee memoria ya devuelta */
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* Suma dos enteros positivos. Si la suma "dio la vuelta" (queda negativa), avisa con -1. */
int suma_segura(int a, int b) {
    int s = a + b;
    if (a > 0 && b > 0 && s < 0)   /* chequeo por desborde */
        return -1;
    return s;
}

int main(int argc, char **argv) {
    int a = atoi(argv[1]), b = atoi(argv[2]);
    printf("suma_segura(%d, %d) = %d\n", a, b, suma_segura(a, b));
    return 0;
}

const a = 2000000000, b = 2000000000;
console.log("suma como número de JavaScript:", a + b);          // 4000000000, exacto en un double
console.log("forzada a 32 bits con |0:", (a + b) | 0);          // da la vuelta: está definido
console.log("a + b > 2147483647:", a + b > 2147483647);         // la pregunta se contesta sin desborde

// el chequeo del programa en C, escrito en JavaScript con enteros de 32 bits "a la fuerza"
function sumaSegura(x, y) {
  const s = (x + y) | 0;                   // aritmética de 32 bits con vuelta
  if (x > 0 && y > 0 && s < 0) return -1;  // acá el chequeo se cumple siempre
  return s;
}
console.log("sumaSegura(2000000000, 2000000000) =", sumaSegura(a, b));
console.log("sumaSegura(5, 7) =", sumaSegura(5, 7));

#include <cstdio>
#include <memory>
#include <stdexcept>
#include <vector>

// Un "recurso": se adquiere en el constructor y se libera en el destructor.
class Candado {
    const char *nombre_;
public:
    explicit Candado(const char *n) : nombre_(n) { std::printf("  + toma %s\n", nombre_); }
    ~Candado() { std::printf("  - suelta %s\n", nombre_); }
    Candado(const Candado &) = delete;            // un recurso, un dueño
    Candado &operator=(const Candado &) = delete;
};

void trabajo(bool falla) {
    Candado a("deposito");
    Candado b("camion");
    std::vector<int> paquetes(1000, 7);            // memoria en el heap, la libera el destructor del vector
    auto etiqueta = std::make_unique<int>(42);     // idem para un solo objeto
    if (falla) throw std::runtime_error("se rompio la cadena de frio");
    std::printf("  trabajo termino bien: %zu paquetes, etiqueta %d\n", paquetes.size(), *etiqueta);
}

int main() {
    std::puts("caso 1: todo sale bien");
    trabajo(false);
    std::puts("caso 2: una excepcion en medio");
    try { trabajo(true); }
    catch (const std::exception &e) { std::printf("  capturada: %s\n", e.what()); }
    return 0;
}
